-- Separate store programme: no scheduled store audits can leak through last-mile queries.
begin;
create table if not exists public.ops_store_audit_master (
 company_id uuid primary key references public.companies(id), version integer not null default 1,
 template jsonb not null, settings jsonb not null, updated_by uuid, updated_at timestamptz not null default now()
);
create table if not exists public.ops_store_audits (
 id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id),
 number text not null, location_id uuid not null references public.stations(id), store_name text not null,
 assigned_to uuid not null references public.profiles(id), assigned_name text not null, scheduled_for timestamptz not null,
 status text not null default 'scheduled' check(status in ('scheduled','in_progress','awaiting_response','under_review','closed','cancelled')),
 template jsonb not null, template_version integer not null, answers jsonb not null default '{}', findings jsonb not null default '[]',
 summary text not null default '', events jsonb not null default '[]', version integer not null default 1,
 started_at timestamptz, completed_at timestamptz, email_sent_at timestamptz, email_error text,
 email_recipients text[] not null default '{}', email_lock_until timestamptz, deleted_at timestamptz,
 created_at timestamptz not null default now(), unique(company_id,number), unique(company_id,id),
 check (status not in ('awaiting_response','under_review','closed') or completed_at is not null)
);
create index if not exists ops_store_audits_scope on public.ops_store_audits(company_id,location_id,scheduled_for desc) where deleted_at is null;
create table if not exists public.ops_store_audit_evidence (
 id uuid primary key default gen_random_uuid(), company_id uuid not null, audit_id uuid not null,
 question_id text not null, phase text not null check(phase in ('audit','response')), file_name text not null,
 content_type text not null, size integer not null check(size>0 and size<=31457280), path text not null unique,
 ready boolean not null default false, uploaded_by uuid not null, created_at timestamptz not null default now(),
 foreign key(company_id,audit_id) references public.ops_store_audits(company_id,id)
);
-- Serialize evidence changes with audit completion and store response submission.
create or replace function public.guard_store_audit_evidence() returns trigger language plpgsql set search_path=public as $$
declare a public.ops_store_audits; item jsonb; max_files integer; existing integer; row_data public.ops_store_audit_evidence;
begin
 row_data := case when TG_OP='DELETE' then OLD else NEW end;
 select * into a from public.ops_store_audits where id=row_data.audit_id and company_id=row_data.company_id for update;
 if a.id is null or a.deleted_at is not null then raise exception 'Audit unavailable'; end if;
 if row_data.phase='audit' and (a.status<>'in_progress' or a.completed_at is not null or a.assigned_to<>row_data.uploaded_by) then raise exception 'Inspection evidence is locked'; end if;
 if row_data.phase='response' and (a.completed_at is null or not exists(select 1 from jsonb_array_elements(a.findings) f where f->>'questionId'=row_data.question_id and f->>'state'='open')) then raise exception 'Store response evidence is locked'; end if;
 select q into item from jsonb_array_elements(a.template->'sections') s cross join lateral jsonb_array_elements(s->'questions') q where q->>'id'=row_data.question_id;
 if item is null then raise exception 'Question unavailable'; end if;
 if TG_OP<>'DELETE' and NEW.ready then
  max_files := (item->(case when NEW.phase='audit' then 'evidence' else 'responseEvidence' end)->>'max')::integer;
  select count(*) into existing from public.ops_store_audit_evidence where audit_id=NEW.audit_id and question_id=NEW.question_id and phase=NEW.phase and ready and id<>NEW.id;
  if existing>=max_files then raise exception 'Attachment limit reached'; end if;
 end if;
 return row_data;
end $$;
drop trigger if exists store_audit_evidence_guard on public.ops_store_audit_evidence;
create trigger store_audit_evidence_guard before insert or update or delete on public.ops_store_audit_evidence for each row execute function public.guard_store_audit_evidence();
create or replace function public.guard_store_audit_completion() returns trigger language plpgsql set search_path=public as $$
declare q jsonb; a jsonb; f jsonb; old_f jsonb; rule jsonb; n integer; required_count integer;
begin
 if NEW.template is distinct from OLD.template or NEW.template_version is distinct from OLD.template_version then raise exception 'Scheduled checklist snapshots cannot be changed'; end if;
 if OLD.completed_at is not null and (NEW.answers is distinct from OLD.answers or NEW.completed_at is distinct from OLD.completed_at or NEW.summary is distinct from OLD.summary) then raise exception 'Completed inspections cannot be changed'; end if;
 if OLD.completed_at is null and NEW.completed_at is not null then
  if OLD.status<>'in_progress' or length(trim(NEW.summary))=0 then raise exception 'Complete the inspection and its summary first'; end if;
  for q in select v from jsonb_array_elements(NEW.template->'sections') s cross join lateral jsonb_array_elements(s->'questions') v loop
   a := NEW.answers->(q->>'id');
   if coalesce(a->>'outcome','')='' and (q->>'required')::boolean then raise exception 'Required answer missing: %',q->>'label'; end if;
   rule := q->'evidence'; required_count := case when a->>'outcome'='na' then 0 when rule->>'when'='always' or (rule->>'when'='gap' and a->>'outcome'='gap') then (rule->>'min')::integer else 0 end;
   select count(*) into n from public.ops_store_audit_evidence where audit_id=NEW.id and question_id=q->>'id' and phase='audit' and ready;
   if a->>'outcome' in ('pass','gap','na') and (n<required_count or n>(rule->>'max')::integer) then raise exception 'Inspection evidence missing or over limit: %',q->>'label'; end if;
  end loop;
 end if;
 for f in select value from jsonb_array_elements(NEW.findings) loop
  select value into old_f from jsonb_array_elements(OLD.findings) where value->>'questionId'=f->>'questionId';
  if f->>'state'='submitted' and coalesce(old_f->>'state','')<>'submitted' then
   select v into q from jsonb_array_elements(NEW.template->'sections') s cross join lateral jsonb_array_elements(s->'questions') v where v->>'id'=f->>'questionId';
   rule:=q->'responseEvidence'; required_count:=case when rule->>'when'='optional' then 0 else (rule->>'min')::integer end;
   select count(*) into n from public.ops_store_audit_evidence where audit_id=NEW.id and question_id=f->>'questionId' and phase='response' and ready;
   if length(trim(coalesce(f->>'note','')))=0 or n<required_count or n>(rule->>'max')::integer then raise exception 'Store closure note or evidence missing'; end if;
  end if;
 end loop;
 return NEW;
end $$;
drop trigger if exists store_audit_completion_guard on public.ops_store_audits;
create trigger store_audit_completion_guard before update on public.ops_store_audits for each row execute function public.guard_store_audit_completion();
create index if not exists ops_store_audit_evidence_audit on public.ops_store_audit_evidence(company_id,audit_id,question_id,phase);
alter table public.ops_store_audit_master enable row level security;
alter table public.ops_store_audits enable row level security;
alter table public.ops_store_audit_evidence enable row level security;
-- Service-role only. All reads (including evidence and exports) use the server's company,
-- configured role, authorized store scope, and completion visibility checks.
revoke all on public.ops_store_audit_master,public.ops_store_audits,public.ops_store_audit_evidence from anon,authenticated;
grant all on public.ops_store_audit_master,public.ops_store_audits,public.ops_store_audit_evidence to service_role;
insert into public.app_pages(company_id,code,name,sort_order,is_active)
select c.id,p.code,p.name,94,true from public.companies c cross join (values ('store_audits','Store Audits'),('store_audit_master','Store Audit Master'))p(code,name)
on conflict(company_id,code) do nothing;
insert into public.role_page_permissions(company_id,role_id,page_id,can_view,can_add,can_edit)
select r.company_id,r.role_id,target.id,r.can_view,r.can_add,r.can_edit
from public.role_page_permissions r join public.app_pages source on source.id=r.page_id and source.company_id=r.company_id
join public.app_pages target on target.company_id=source.company_id and target.code=case source.code when 'station_audits' then 'store_audits' else 'store_audit_master' end
where source.code in ('station_audits','station_audit_master')
on conflict(company_id,role_id,page_id) do nothing;
insert into public.ops_store_audit_master(company_id,template,settings)
select c.id,$apollo${"name": "Amazon Now \u00b7 Apollo store audit", "description": "Based on Apollo Audit Readiness Checklist, supplied 15 Oct 2026. Questions and evidence rules are editable. Surprise audit: stores see results only after completion.", "sections": [{"id": "priority", "name": "Fix first", "guidance": "Priority checks: repeated failures in the source checklist.", "questions": [{"id": "priority_01", "label": "Expiry removal: zero physical vs. system mismatch; remove every expired unit in system before disposal", "guidance": "Show the physical expiry check and matching system removal record.", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Remove expired units in the system, reconcile the physical quantity and dispose under SOP.", "hours": 24, "severity": "high"}, {"id": "priority_02", "label": "Cleaning & sanitation record displayed & updated to date", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Update and display the cleaning and sanitation record.", "hours": 24, "severity": "high"}, {"id": "priority_03", "label": "Liquid items stowed vertically", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Restow liquid items vertically and inspect for leakage.", "hours": 24, "severity": "high"}, {"id": "priority_04", "label": "Cleaning schedule available at site", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Display the current cleaning schedule and assign responsibility.", "hours": 24, "severity": "high"}, {"id": "priority_05", "label": "No dust in food bins", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Clean affected bins and verify the cleaning frequency.", "hours": 24, "severity": "high"}, {"id": "priority_06", "label": "Deckling plates not damaged", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Replace or repair damaged deckling plates.", "hours": 24, "severity": "high"}, {"id": "priority_07", "label": "No over-stuffing / over-hanging (check 5 bays)", "guidance": "Inspect five bays; record their identifiers and each exception.", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Restow affected bays within their safe capacity.", "hours": 24, "severity": "high"}, {"id": "priority_08", "label": "UTR roster pasted & visible to staff", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Display the current UTR roster.", "hours": 24, "severity": "high"}, {"id": "priority_09", "label": "Partner escalation matrix documented & displayed", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Update and display the escalation matrix.", "hours": 24, "severity": "high"}, {"id": "priority_10", "label": "Long ASINs kept in bat bins", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Move long ASINs into the designated bat bins.", "hours": 24, "severity": "high"}, {"id": "priority_11", "label": "No food spillage beneath racks / bins", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Remove spillage and clean beneath the affected racks and bins.", "hours": 24, "severity": "high"}, {"id": "priority_12", "label": "PGT tasks performed regularly", "guidance": "Check recent task records and execution.", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Complete overdue PGT tasks and record the recurring owner.", "hours": 24, "severity": "high"}]}, {"id": "hygiene", "name": "Hygiene & Upkeep", "guidance": "", "questions": [{"id": "hygiene_01", "label": "No liquid ASIN leakage", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Isolate leaking stock and clean the affected storage area.", "hours": 48, "severity": "normal"}, {"id": "hygiene_02", "label": "Washrooms clean (UTR + rider)", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Clean both washrooms and update the cleaning record.", "hours": 48, "severity": "normal"}]}, {"id": "food", "name": "Food Safety", "guidance": "Record actual readings and affected areas where relevant. Thresholds below are transcribed from the supplied checklist.", "questions": [{"id": "food_01", "label": "Veg / non-veg & food / non-food on separate shelves", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Segregate the affected stock onto separate shelves.", "hours": 24, "severity": "high"}, {"id": "food_02", "label": "No leakage on any building wall", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Raise a repair action and protect stock from the affected wall.", "hours": 24, "severity": "high"}, {"id": "food_03", "label": "Product temperature validated on addback from CRET001", "guidance": "Record the product temperature and supporting return/addback record.", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Validate product temperature and follow the approved addback process.", "hours": 24, "severity": "high"}, {"id": "food_04", "label": "Bin dividers present (2 aisles each: Ambient, Tropical, Chiller, Frozen)", "guidance": "Check two aisles in each listed zone.", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Install missing dividers in the identified aisles.", "hours": 24, "severity": "high"}, {"id": "food_05", "label": "Chiller temperature 0 to 5 C (+/- 4 C)", "guidance": "Record the measured temperature and a photo of the reading.", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Escalate temperature deviation, protect stock and verify the corrected reading.", "hours": 24, "severity": "high"}, {"id": "food_06", "label": "Rodent traps at designated locations", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Restore designated trap placement and escalate pest activity.", "hours": 24, "severity": "high"}, {"id": "food_07", "label": "Frozen temperature -22 to -18 C (+/- 4 C)", "guidance": "Record the measured temperature and a photo of the reading.", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Escalate temperature deviation, protect stock and verify the corrected reading.", "hours": 24, "severity": "high"}, {"id": "food_08", "label": "Frozen / meat / seafood in chilled bags with min. 2 gel pads", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Repack affected items in chilled bags with at least two gel pads.", "hours": 24, "severity": "high"}]}, {"id": "quality", "name": "Quality", "guidance": "", "questions": [{"id": "quality_01", "label": "Unshaped / small items (non six-side) in drawer bins", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Move applicable items into drawer bins.", "hours": 48, "severity": "normal"}, {"id": "quality_02", "label": "Big & soft items in single layer", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Restow big and soft items in a single layer.", "hours": 48, "severity": "normal"}, {"id": "quality_03", "label": "Punnets (fruit / veg) max 2 layers, lid up", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Restow punnets lid-up, no more than two layers.", "hours": 48, "severity": "normal"}, {"id": "quality_04", "label": "Simple Bin Count, Simple Record Count & Cycle Count closed by shift end", "guidance": "Check the shift-end count records.", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Complete and close outstanding counts with the shift owner.", "hours": 48, "severity": "normal"}, {"id": "quality_05", "label": "MAP / cover items stowed vertically", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Restow MAP/cover items vertically.", "hours": 48, "severity": "normal"}, {"id": "quality_06", "label": "Corrugated box items stowed horizontally", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Restow corrugated box items horizontally.", "hours": 48, "severity": "normal"}, {"id": "quality_07", "label": "No heavy items on top of light / fragile IDs", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Remove heavy items from light or fragile stock.", "hours": 48, "severity": "normal"}, {"id": "quality_08", "label": "Quality Manager aware of roles & responsibilities", "guidance": "Record the discussion and knowledge gaps.", "required": true, "allowNA": true, "evidence": {"when": "gap", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Brief the Quality Manager and verify understanding.", "hours": 48, "severity": "normal"}, {"id": "quality_09", "label": "No rotten / over / under-ripe products in bins", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Remove unsuitable produce and inspect neighbouring bins.", "hours": 48, "severity": "normal"}, {"id": "quality_10", "label": "QRC / quality OPLs pasted at store", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Display the current QRC / quality OPLs.", "hours": 48, "severity": "normal"}]}, {"id": "picker", "name": "Picker Knowledge", "guidance": "Quiz two pickers on the floor. Record who was checked and any coaching needed.", "questions": [{"id": "picker_01", "label": "Hazmat kept in separate bags", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "gap", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Coach both pickers and demonstrate separate hazmat packing.", "hours": 48, "severity": "normal"}, {"id": "picker_02", "label": "Correct bag size per order (basis units)", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "gap", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Coach pickers on bag selection based on order units.", "hours": 48, "severity": "normal"}, {"id": "picker_03", "label": "Veg / non-veg kept in separate bags", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "gap", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Coach pickers and demonstrate separate packing.", "hours": 48, "severity": "normal"}, {"id": "picker_04", "label": "Damage process understood & followed", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "gap", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Brief the damage process and verify understanding.", "hours": 48, "severity": "normal"}, {"id": "picker_05", "label": "Six-side (title) check followed", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "gap", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Demonstrate the six-side check and verify execution.", "hours": 48, "severity": "normal"}]}, {"id": "people", "name": "People Presence & Knowledge", "guidance": "", "questions": [{"id": "people_01", "label": "Process Expert aware of responsibilities", "guidance": "Record the discussion and knowledge gaps.", "required": true, "allowNA": true, "evidence": {"when": "gap", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Brief the Process Expert and verify understanding.", "hours": 48, "severity": "normal"}, {"id": "people_02", "label": "Adequate staffing planned at store", "guidance": "Review the roster against the staffing plan.", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Correct the staffing plan and assign shift coverage.", "hours": 48, "severity": "normal"}]}, {"id": "compliance", "name": "Compliance & Documents", "guidance": "Keep one valid copy of each in a station file. Capture the document and validity where applicable.", "questions": [{"id": "compliance_01", "label": "Pest control contract available & valid", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Obtain or renew the pest control contract and retain a valid copy.", "hours": 48, "severity": "normal"}, {"id": "compliance_02", "label": "Emergency contacts displayed", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Display current emergency contact details.", "hours": 48, "severity": "normal"}, {"id": "compliance_03", "label": "Contract Labour (R&A) Act certificate available", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Obtain and file the applicable certificate.", "hours": 48, "severity": "normal"}, {"id": "compliance_04", "label": "GST APOB available", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Obtain and file the GST APOB.", "hours": 48, "severity": "normal"}, {"id": "compliance_05", "label": "Trade license available & valid", "guidance": "", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Obtain or renew the trade licence and retain a valid copy.", "hours": 48, "severity": "normal"}]}, {"id": "integrity", "name": "Integrity Checks", "guidance": "", "questions": [{"id": "integrity_01", "label": "No physical vs. virtual mismatch on recommended-ASIN audit", "guidance": "Record ASINs checked and the physical/system quantities.", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Investigate each difference and reconcile the physical and system quantities.", "hours": 24, "severity": "high"}, {"id": "integrity_02", "label": "Expiry products disposed as per SOP", "guidance": "Check the disposal record and system removal evidence.", "required": true, "allowNA": true, "evidence": {"when": "always", "min": 1, "max": 5}, "responseEvidence": {"when": "always", "min": 1, "max": 5}, "action": "Correct the disposal process and retain the required records.", "hours": 24, "severity": "high"}]}]}$apollo$::jsonb, jsonb_build_object(
'managerRoles',coalesce(to_jsonb(s.scheduler_role_ids),'[]'::jsonb),
'responderRoles',coalesce(to_jsonb(s.responder_role_ids),'[]'::jsonb),
'modelIds',coalesce((select jsonb_agg(m.id) from public.location_models m where m.company_id=c.id and upper(m.code)='NOW'),'[]'::jsonb),
'emailEnabled',true,'ccRules',jsonb_build_array('people_reporting_chain','company_owners'))
from public.companies c left join public.ops_audit_programme_settings s on s.company_id=c.id
on conflict(company_id) do nothing;
notify pgrst,'reload schema';
commit;
